■ 关键代码段
```c
/* app_power.c: power_enter_soft_sleep() */
static void power_enter_soft_sleep(void)
{
    if (s_sleeping) return;
    s_sleeping = true;
    ESP_LOGI(TAG, "进入软省电：背光降到最小（%d%%）+ WiFi 最大省电档 + 屏蔽录音键（touch/IMU 可唤醒）",
             APP_LCD_BRIGHTNESS_MIN);
    lcd_brightness_set(APP_LCD_BRIGHTNESS_MIN);
    if (net_is_initialized()) {
        esp_err_t err = net_set_power_save(true);
        if (err == ESP_OK) ESP_LOGI(TAG, "WiFi 已切到最大省电档（保持连接）");
        else if (err != ESP_ERR_INVALID_STATE) ESP_LOGW(TAG, "WiFi 省电切换失败：%s（保持原功耗档）", esp_err_to_name(err));
    } else {
        ESP_LOGI(TAG, "WiFi 未初始化：本次只降背光、屏蔽录音键");
    }
}

/* app_power.c: power_leave_soft_sleep() */
static void power_leave_soft_sleep(void)
{
    if (!s_sleeping) return;
    s_sleeping = false;
    if (net_is_initialized()) {
        esp_err_t err = net_set_power_save(false);
        if (err == ESP_OK) ESP_LOGI(TAG, "WiFi 已恢复默认功耗档");
        else if (err != ESP_ERR_INVALID_STATE) ESP_LOGW(TAG, "恢复 WiFi 功耗档失败：%s", esp_err_to_name(err));
    }
    int restore = app_settings_get_backlight();
    lcd_brightness_set(restore);
    s_last_active_ms = power_now_ms();
    ESP_LOGI(TAG, "退出软省电：背光恢复到 %d%%、WiFi 回默认功耗档、录音键解禁", restore);
}

/* app_power.c: 主循环 */
for (;;) {
    uint32_t now    = power_now_ms();
    bool     active = power_touch_pressed() || power_imu_moved() || bsp_gpio_key_is_pressed();

    if (s_sleeping) {
        if (active) power_leave_soft_sleep();          /* 内部刷新 s_last_active_ms */
        else { vTaskDelay(pdMS_TO_TICKS(APP_POWER_SLEEP_POLL_MS)); continue; }
    } else {
        if (active) s_last_active_ms = now;
        uint32_t idle = now - s_last_active_ms;
        if (s_timeout_ms > 0 && idle >= (uint32_t)s_timeout_ms && power_can_sleep()) {
            ESP_LOGI(TAG, "空闲 %" PRIu32 " ms ≥ 超时 %" PRIu32 " ms，进入软省电", idle, (uint32_t)s_timeout_ms);
            power_enter_soft_sleep();
            vTaskDelay(pdMS_TO_TICKS(APP_POWER_SLEEP_POLL_MS));
            continue;
        }
    }
    vTaskDelay(pdMS_TO_TICKS(APP_POWER_SAMPLE_MS));
}
```
```c
/* app_key.c: APP_KEY_EVENT_PRESS 分支最前面（app_key.c:260-272 附近） */
case APP_KEY_EVENT_PRESS:
    if (app_power_is_sleeping()) {
